package com.agritech.web;
import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import org.springframework.ui.Model; import org.springframework.jdbc.core.JdbcTemplate;
@Controller public class HomeController {
 private final JdbcTemplate db; public HomeController(JdbcTemplate db){this.db=db;}
 @GetMapping({"/","/dashboard"}) public String dashboard(Model m){m.addAttribute("farmCount",safeCount("SELECT COUNT(*) FROM farms"));m.addAttribute("cropCount",safeCount("SELECT COUNT(*) FROM crops"));m.addAttribute("soilCount",safeCount("SELECT COUNT(*) FROM soil_readings"));m.addAttribute("irrigationCount",safeCount("SELECT COUNT(*) FROM irrigation_schedules WHERE status='PLANNED'"));return "dashboard";}
 @GetMapping("/login") public String login(){return "login";}
 @GetMapping("/farms") public String farms(Model m){m.addAttribute("farms",db.queryForList("SELECT * FROM farms ORDER BY id DESC"));return "farms";}
 @PostMapping("/farms") public String addFarm(@RequestParam String name,@RequestParam String location,@RequestParam double area,@RequestParam String soilType){db.update("INSERT INTO farms(name,location,area_acres,soil_type) VALUES(?,?,?,?)",name,location,area,soilType);return "redirect:/farms";}
 @GetMapping("/crops") public String crops(Model m){m.addAttribute("crops",db.queryForList("SELECT c.*,f.name farm_name FROM crops c LEFT JOIN farms f ON c.farm_id=f.id ORDER BY c.id DESC"));m.addAttribute("farms",db.queryForList("SELECT id,name FROM farms"));return "crops";}
 @PostMapping("/crops") public String addCrop(@RequestParam int farmId,@RequestParam String cropName,@RequestParam String variety,@RequestParam String sowingDate){db.update("INSERT INTO crops(farm_id,crop_name,variety,sowing_date,status) VALUES(?,?,?,?, 'GROWING')",farmId,cropName,variety,sowingDate);return "redirect:/crops";}
 @GetMapping("/soil") public String soil(Model m){m.addAttribute("readings",db.queryForList("SELECT s.*,f.name farm_name FROM soil_readings s JOIN farms f ON s.farm_id=f.id ORDER BY s.recorded_at DESC LIMIT 50"));m.addAttribute("farms",db.queryForList("SELECT id,name FROM farms"));return "soil";}
 @PostMapping("/soil") public String addSoil(@RequestParam int farmId,@RequestParam double ph,@RequestParam double moisture,@RequestParam double nitrogen,@RequestParam double phosphorus,@RequestParam double potassium){db.update("INSERT INTO soil_readings(farm_id,ph,moisture,nitrogen,phosphorus,potassium) VALUES(?,?,?,?,?,?)",farmId,ph,moisture,nitrogen,phosphorus,potassium);return "redirect:/soil";}
 @GetMapping("/irrigation") public String irrigation(Model m){m.addAttribute("items",db.queryForList("SELECT i.*,f.name farm_name FROM irrigation_schedules i JOIN farms f ON i.farm_id=f.id ORDER BY scheduled_at DESC"));m.addAttribute("farms",db.queryForList("SELECT id,name FROM farms"));return "irrigation";}
 @PostMapping("/irrigation") public String addIrrigation(@RequestParam int farmId,@RequestParam String scheduledAt,@RequestParam double waterLitres,@RequestParam String notes){db.update("INSERT INTO irrigation_schedules(farm_id,scheduled_at,water_litres,notes,status) VALUES(?,?,?,?,'PLANNED')",farmId,scheduledAt.replace('T',' ')+":00",waterLitres,notes);return "redirect:/irrigation";}
 @GetMapping("/analytics") public String analytics(Model m){m.addAttribute("yieldRows",db.queryForList("SELECT crop_name, SUM(actual_yield_kg) yield_kg FROM harvest_records GROUP BY crop_name"));return "analytics";}
 private int safeCount(String sql){try{return db.queryForObject(sql,Integer.class);}catch(Exception e){return 0;}}
}